cards.state_display:
[[[
  const d = Number(entity.state);
  if (!Number.isFinite(d)) return entity.state.toUpperCase();
  if (d === 0) return 'TODAY';
  if (d === 1) return 'TOMORROW';
  return `IN ${d} DAYS`;
]]]

card.border:
[[[
  const d = Number(entity.state);
  if (d === 0) return '3px solid rgba(255,82,82,.98)';
  if (d === 1) return '3px solid rgba(255,82,82,.82)';
  return '1px solid rgba(255,255,255,.12)';
]]]

card.background:
[[[
  const d = Number(entity.state);
  if (d === 0) return 'linear-gradient(145deg, rgba(244,67,54,.55), rgba(183,28,28,.28))';
  if (d === 1) return 'linear-gradient(145deg, rgba(244,67,54,.38), rgba(183,28,28,.18))';
  return 'linear-gradient(145deg, rgba(55,55,62,.72), rgba(25,25,30,.88))';
]]]

card.box-shadow:
[[[
  const d = Number(entity.state);
  if (d <= 1) return '0 0 20px rgba(244,67,54,.28)';
  return '0 6px 18px rgba(0,0,0,.18)';
]]]

