cards.icon:
[[[
  const garage = entity;
  if (!garage) return 'mdi:garage-alert';
  if (garage.state === 'closed') return 'mdi:garage';
  if (garage.state === 'open') return 'mdi:garage-open';
  return 'mdi:garage-open-variant';
]]]

cards.label:
[[[
  const garage = entity;
  if (!garage) return 'NOT FOUND';
  return garage.state.replaceAll('_', ' ').toUpperCase();
]]]

card.border:
[[[
  const garage = entity;
  if (!garage) return '1px solid rgba(255,255,255,.16)';
  if (garage.state === 'closed') return '2px solid rgba(80,200,90,.85)';
  if (['open','opening','closing'].includes(garage.state)) {
    return '2px solid rgba(255,82,82,.88)';
  }
  return '1px solid rgba(255,255,255,.16)';
]]]

card.background:
[[[
  const garage = entity;
  if (!garage) return 'linear-gradient(90deg, rgba(70,70,80,.35), rgba(35,35,42,.80))';
  if (garage.state === 'closed') {
    return 'linear-gradient(90deg, rgba(76,175,80,.28), rgba(0,150,136,.14))';
  }
  if (['open','opening','closing'].includes(garage.state)) {
    return 'linear-gradient(90deg, rgba(244,67,54,.30), rgba(255,87,34,.14))';
  }
  return 'linear-gradient(90deg, rgba(70,70,80,.35), rgba(35,35,42,.80))';
]]]

icon.color:
[[[
  const garage = entity;
  if (!garage) return '#9e9e9e';
  if (garage.state === 'closed') return '#66bb6a';
  if (['opening','closing'].includes(garage.state)) return '#ffb74d';
  if (garage.state === 'open') return '#ff5252';
  return '#9e9e9e';
]]]

label.background:
[[[
  const garage = entity;
  if (!garage) return 'rgba(117,117,117,.82)';
  if (garage.state === 'closed') return 'rgba(46,125,50,.92)';
  if (['opening','closing'].includes(garage.state)) return 'rgba(239,108,0,.92)';
  if (garage.state === 'open') return 'rgba(198,40,40,.94)';
  return 'rgba(117,117,117,.82)';
]]]

